Q: Ansible split based on a list of strings and with the input being a list A: <p>I ended creating a <a href="https://docs.ansible.com/projects/ansible/latest/dev_guide/developing_plugins.html#filter-plugins" rel="nofollow noreferrer">Custom Filter Plugin</a>:</p>
<pre class="lang-py prettyprint-override"><code>#!/usr/bin/python3

class FilterModule(object):

    def filters(self):
        return {
            'split_multi_contains': self.split_multi_contains
        }

    def split_multi_contains( self, inputList, needleList, delimiter = ' ', delimiter_limit = -1 ):
        result = []
        for inputItem in inputList :
            splitFound=False
            for needleItem in needleList :
                if  needleItem in inputItem :
                    result.append(inputItem.split(delimiter,delimiter_limit))
                    splitFound=True
            if splitFound == False :
                result.append(inputItem)
        return result
